--- pgdelta=true ---
set local check_function_bodies = off;

create extension "pg_net" schema "extensions";

create table "public"."m_t" (
  "id"    bigint generated always as identity not null,
  "owner" uuid,
  "body"  text,
  constraint "m_t_pkey" primary key (id)
);

alter table "public"."m_t"
  enable row level security;

revoke all on table "public"."m_t" from "anon";

create table "public"."q_t" (
  "id"    bigint generated always as identity not null,
  "owner" uuid,
  "body"  text,
  constraint "q_t_pkey" primary key (id)
);

alter table "public"."q_t"
  enable row level security;

revoke all on table "public"."q_t" from "anon";

alter table "public"."bn_base"
  add column "q_col" text;

alter table "public"."bn_base"
  add column "m_col" text;

create or replace function public.m_fn (
  a integer
)
  returns integer
  language sql
  immutable
  AS $function$ select a + 1 $function$;

create or replace function public.q_fn (
  a integer
)
  returns integer
  language sql
  immutable
  AS $function$ select a + 1 $function$;

create index m_idx on public.bn_base using btree (m_col);

create index q_idx on public.bn_base using btree (q_col);

create policy "m_own" on "public"."m_t"
  for select
  to "authenticated"
  using ((owner = auth.uid()));

create policy "q_own" on "public"."q_t"
  for select
  to "authenticated"
  using ((owner = auth.uid()));

comment on extension "pg_net" is 'Async HTTP';

grant execute on function "public"."m_fn"(integer) to public, "anon", "authenticated", "postgres", "service_role";

grant execute on function "public"."q_fn"(integer) to public, "anon", "authenticated", "postgres", "service_role";

revoke all on table "public"."m_t" from "authenticated";

grant select on table "public"."m_t" to "authenticated";

grant delete, insert, maintain, references, select, trigger, truncate, update on table "public"."m_t" to "postgres", "service_role";

revoke all on table "public"."q_t" from "authenticated";

grant select on table "public"."q_t" to "authenticated";

grant delete, insert, maintain, references, select, trigger, truncate, update on table "public"."q_t" to "postgres", "service_role";

